var i=[{title:`Переваги`,text:`Кожна рука несе власне навантаження, що робить односторонню роботу практичною і дозволяє кути хвату, яких фіксований гриф може не дати. Тяга однією рукою чи жим однією рукою можуть показати різницю в контролі між вашими сторонами. Гантелі часто краще вміщуються в малих просторах, ніж повне налаштування зі штангою, хоча стрибки між вагами можуть бути великими, а вибір обмеженим.`},{title:`Оберіть вагу`,text:`Оберіть пару чи одну гантель, що дає змогу досягти цільових повторень зі стабільним рухом і кількома повтореннями в запасі. Як початківцю вам можуть знадобитися різні навантаження для тяг, згинань і жимів. Якщо наступна вага завелика, спершу додайте повторення, амплітуду чи контроль із легшою.`},{title:`Безпечно займіть положення`,text:`Для жиму лежачи сядьте з гантелями, надійно утримуваними біля стегон, відкиньтеся під контролем і виведіть ваги в положення, не підкидаючи їх. Для підйомів стоячи піднімайте ваги ногами й тулубом у стабільному положенні. Не кидайте ваги там, де вони можуть відскочити на ваші стопи, пошкодити підлогу чи вдарити когось.`},{title:`Поширені застосування`,text:`Кубкові присіди та румунська станова тяга з гантелями тренують низ тіла, тяги з опорою та жими охоплюють верх тіла, а перенесення розвивають хват і контроль тулуба. Якщо у вас лише одна гантель, використовуйте її для односторонніх рухів.`},{title:`Як це працює в TrainUp`,text:`У Профілі вкажіть ваги гантелей, які у вас є. Ваш план добирає вправи, що відповідають вашому обладнанню, простору та висоті стелі. Він не призначає ваги, тож навантаження обираєте ви. Якщо ви нотуєте навантаження після тренування, записуйте їх щоразу однаково, наприклад «12 кг на руку».`}];var l=[{label:`Mayo Clinic: вільні ваги проти тренажерів`,url:`https://www.augustahealth.com/answer/weight-training-free-weights-vs-machine-weights/`},{label:`Бібліотека вправ ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: техніка силових тренувань (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var s={sections:i,sources:l};export{s as default,i as sections,l as sources};